/**
 * ─────────────────────────────────────────────────────────────────────────
 *  Payments.jsx — Payment Management module
 *
 *  Two tabs:
 *    • Payments — read-only history of every payment collected against a
 *      sale (auto-generated by the backend on sale completion / loan
 *      repayment). Search, filter (method / bank / date range), sort,
 *      and paginate. ADMIN can edit the note/reference or delete a record;
 *      WORKER has view-only access.
 *    • Banks — CRUD (create, edit, deactivate, delete) for the banks the
 *      store accepts payments through, with search. ADMIN only for writes;
 *      WORKER can view (read-only) so the list makes sense to them, but the
 *      Sales-form bank picker itself pulls from a separate lightweight
 *      endpoint (getActiveBanks), not this page.
 *
 *  Every record shown here is already de-identified by the backend —
 *  payment/sale database ids are never sent to the client. Payments only
 *  carry human-facing codes (PAY-000123 / SALE-000045).
 * ─────────────────────────────────────────────────────────────────────────
 */
import { useState, useEffect } from 'react';
import {
  Search, Plus, Trash2, Edit2, Wallet, Landmark, Receipt,
  ChevronLeft, ChevronRight, X, RefreshCw, Calendar,
  CheckCircle, ArrowUpDown, Ban, CheckCircle2,
} from 'lucide-react';
import {
  getPaymentsPage, updatePaymentNotes, deletePayment,
  getBanksPage, createBank, updateBank, deleteBank,
} from '../services/api';

